script:
// Fogaskerék-áttétel: két evolvens fogazatú kerék, helyesen kapcsolódva
// Gear ratio: two involute spur gears that mesh correctly
stage(1000, 600, "#fbfbf8");
title({hu: "Fogaskerék-áttétel", en: "Gear ratio"});
param("z1", {hu: "Hajtó kerék fogszáma z₁", en: "Driving gear teeth z₁"}, 8, 40, 12, 1, "");
param("z2", {hu: "Hajtott kerék fogszáma z₂", en: "Driven gear teeth z₂"}, 8, 60, 30, 1, "");
param("n1", {hu: "Hajtó fordulatszám n₁", en: "Driving speed n₁"}, 0, 60, 15, 1, "1/min");

const ALPHA = deg(20);                       // kapcsolószög 20° (szabványos) / pressure angle 20° (standard)
const inv = a => tan(a) - a;                 // evolvens függvény / involute function

// Egy kerék körvonala: z fog, m modul (px), a = elfordulás (rad)
// Outline of one gear: z teeth, module m (px), turned by angle a (rad)
function gearOutline(z, m, a) {
  const rp = m * z / 2;                      // osztókör sugara / pitch radius
  const rb = rp * cos(ALPHA);                // alapkör (ebből gördül le az evolvens) / base circle
  const ra = rp + m;                         // fejkör / tip circle
  const rf = rp - 1.25 * m;                  // lábkör / root circle
  const pts = [];
  for (let k = 0; k < z; k++) {
    const c = a + k * 2 * PI / z;            // a k-adik fog középvonala / centre line of tooth k
    // A fog fél vastagsága szögben, r sugáron: ψ(r) = π/2z + inv(α) − inv(αr), ahol cos αr = rb/r
    // Half tooth thickness as an angle at radius r
    const half = r => PI / (2 * z) + inv(ALPHA) - inv(acos(min(1, rb / r)));
    const flank = [];
    for (let s = 0; s <= 6; s++) {
      const r = lerp(max(rb, rf), ra, s / 6);
      flank.push([r, half(r)]);
    }
    const hb = half(max(rb, rf));
    pts.push([rf * cos(c - hb), rf * sin(c - hb)]);                    // fogtő bal / root, left
    for (const [r, h] of flank) pts.push([r * cos(c - h), r * sin(c - h)]);          // bal fogfelület / left flank
    for (const [r, h] of flank.reverse()) pts.push([r * cos(c + h), r * sin(c + h)]); // jobb fogfelület / right flank
    pts.push([rf * cos(c + hb), rf * sin(c + hb)]);                    // fogtő jobb / root, right
  }
  return pts;
}

let th1 = 0;                                 // a hajtó kerék szöge (rad) / angle of the driving gear
update(dt => { th1 += 2 * PI * P.n1 / 60 * dt; });   // ω = 2π·n/60

draw(t => {
  const z1 = P.z1, z2 = P.z2;
  // A modult (px) úgy választjuk, hogy a pár mindig kiférjen / module in px chosen so the pair always fits
  const m = min(860 / (z1 + z2 + 4), 420 / (max(z1, z2) + 2.5));
  const r1 = m * z1 / 2, r2 = m * z2 / 2;
  const cy = 350;                            // a tengelyek magassága / height of the shafts
  const cx1 = 500 - r2;                      // így a pár a vászon közepére kerül / this centres the pair
  const cx2 = cx1 + r1 + r2;                 // tengelytávolság a = r₁ + r₂ / centre distance
  // Gördülés: r₁·θ₁ = −r₂·θ₂. A kezdő eltolás (π + π/z₂) miatt a kerék fogárka áll szemben az első fogával
  // Rolling: r₁·θ₁ = −r₂·θ₂; the offset puts a tooth gap of gear 2 opposite a tooth of gear 1
  const th2 = PI + PI / z2 - th1 * z1 / z2;

  for (const [cx, z, a, col] of [[cx1, z1, th1, C.orange], [cx2, z2, th2, C.blue]]) {
    const pts = gearOutline(z, m, a).map(([x, y]) => [cx + x, cy + y]);
    polygon(pts, {fill: col, stroke: C.ink, lw: 1.5, alpha: 0.85});
    circle(cx, cy, m * z / 2, {stroke: C.ink, lw: 1, dash: [5, 4], fill: null});   // osztókör / pitch circle
    circle(cx, cy, 0.25 * m * z / 2 + 6, {fill: "#fff", stroke: C.ink});           // agy / hub
    line(cx, cy, cx + 0.8 * m * z / 2 * cos(a), cy + 0.8 * m * z / 2 * sin(a), {stroke: C.ink, lw: 3});   // jelölő / marker
  }
  text({hu: "hajtó", en: "driving"}, cx1, cy + r1 + m + 30, {align: "center", size: 16});
  text({hu: "hajtott", en: "driven"}, cx2, cy + r2 + m + 30, {align: "center", size: 16});

  const i = z2 / z1;                         // áttétel / gear ratio
  text("i = z₂ / z₁ = " + z2 + " / " + z1 + " = " + fmt(i, 2), 500, 100, {align: "center", size: 22, bold: true});
  show({hu: "Áttétel i = z₂/z₁", en: "Gear ratio i = z₂/z₁"}, i, "", 2);
  show({hu: "Hajtott fordulatszám n₂ = n₁/i", en: "Driven speed n₂ = n₁/i"}, P.n1 / i, "1/min", 1);
  show({hu: "Nyomaték-szorzó M₂/M₁ = i (veszteség nélkül)", en: "Torque factor M₂/M₁ = i (no losses)"}, i, "", 2);
  plot("n₁", P.n1, {unit: "1/min", color: C.orange, min: 0, group: "n"});
  plot("n₂", P.n1 / i, {unit: "1/min", color: C.blue, min: 0, group: "n"});
});
